    }
    return un;
}

// Scheme 3: Newmark average acceleration
Vector3d scheme3(double dt, int nsteps) {
    double beta=0.25, gamma=0.5;
    Matrix3d Keff = M/(beta*dt*dt) + K;
    Vector3d u=u0, v=v0, a=-K*u0;
    for (int n=0;n<nsteps;++n){
